SourceCode.Declaration:
/// <summary>
/// Data contract class for the cleanup of in- and outbound messages
/// </summary>
[DataContract]
class OMGMessageTableCleanupContract
{
    NoYesId     cleanInbound;
    NoYesId     cleanOutbound;

}

Method.Source:
[DataMemberAttribute, SysOperationLabelAttribute(literalStr("@OMG:CleanupInboundMessages"))]
public NoYesId parmCleanInbound(NoYesId _cleanInbound = cleanInbound)
{
    cleanInbound = _cleanInbound;
    return cleanInbound;
}

[DataMemberAttribute, SysOperationLabelAttribute(literalStr("@OMG:CleanupOutboundMessages"))]
public NoYesId parmCleanOutbound(NoYesId _cleanOutbound = cleanOutbound)
{
    cleanOutbound = _cleanOutbound;
    return cleanOutbound;
}
